import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiTrash2, FiEye, FiPlus } from 'react-icons/fi';

const SellerDashboard = () => {
    const { user } = useAuth();
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState({ totalProducts: 0, totalViews: 0 });

    useEffect(() => {
        fetchProducts();
    }, []);

    useEffect(() => {
        if (products.length > 0) {
            const totalViews = products.reduce((sum, p) => sum + (p.views || 0), 0);
            setStats({
                totalProducts: products.length,
                totalViews: totalViews
            });
        }
    }, [products]);

    const fetchProducts = async () => {
        try {
            const response = await api.get(`/products/seller/${user.id}`);
            setProducts(response.data.products);
        } catch (error) {
            console.error('Erro ao buscar produtos:', error);
            toast.error('Erro ao carregar anúncios');
        } finally {
            setLoading(false);
        }
    };

    const deleteProduct = async (id) => {
        if (!window.confirm('Tem certeza que deseja remover este anúncio?')) return;
        
        try {
            await api.delete(`/products/${id}`);
            toast.success('Anúncio removido com sucesso!');
            fetchProducts();
        } catch (error) {
            toast.error('Erro ao remover anúncio');
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
            </div>
        );
    }

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getStatusBadge = (status) => {
        if (status === 'active') {
            return <span className="px-2 py-1 text-xs rounded-full bg-green-100 text-green-600">Ativo</span>;
        }
        return <span className="px-2 py-1 text-xs rounded-full bg-gray-100 text-gray-600">Inativo</span>;
    };

    return (
        <div>
            {/* Header do Dashboard */}
            <div className="bg-gradient-to-r from-primary-600 to-primary-800 text-white rounded-2xl p-6 mb-8">
                <h1 className="text-2xl font-bold mb-2">Meu Painel</h1>
                <p className="opacity-90">Gerencie seus anúncios e acompanhe suas vendas</p>
            </div>

            {/* Estatísticas do Vendedor */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                <div className="bg-white rounded-xl shadow-md p-6 text-center">
                    <div className="text-3xl font-bold text-primary-600 mb-2">{stats.totalProducts}</div>
                    <div className="text-gray-600">Total de Anúncios</div>
                </div>
                <div className="bg-white rounded-xl shadow-md p-6 text-center">
                    <div className="text-3xl font-bold text-primary-600 mb-2">{stats.totalViews}</div>
                    <div className="text-gray-600">Visualizações Totais</div>
                </div>
            </div>

            {/* Botão Criar Anúncio */}
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold">Meus Anúncios</h2>
                <Link to="/create-product" className="bg-primary-600 text-white px-4 py-2 rounded-lg hover:bg-primary-700 transition flex items-center gap-2">
                    <FiPlus />
                    Novo Anúncio
                </Link>
            </div>

            {/* Lista de Anúncios */}
            {products.length === 0 ? (
                <div className="bg-white rounded-xl shadow-md p-12 text-center">
                    <p className="text-gray-500 mb-4">Você ainda não tem anúncios.</p>
                    <Link to="/create-product" className="text-primary-600 hover:underline">
                        Criar meu primeiro anúncio
                    </Link>
                </div>
            ) : (
                <div className="bg-white rounded-xl shadow-md overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Produto</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Preço</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Estado</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Visualizações</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200">
                                {products.map(product => (
                                    <tr key={product.id} className="hover:bg-gray-50">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                {product.photos && product.photos[0] ? (
                                                    <img 
                                                        src={`http://localhost:3001${product.photos[0]}`} 
                                                        alt={product.title}
                                                        className="w-12 h-12 object-cover rounded-lg"
                                                    />
                                                ) : (
                                                    <div className="w-12 h-12 bg-gray-100 rounded-lg flex items-center justify-center text-2xl">
                                                        {getCategoryIcon(product.category)}
                                                    </div>
                                                )}
                                                <div>
                                                    <div className="font-medium text-gray-900">{product.title}</div>
                                                    <div className="text-sm text-gray-500">{product.category}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-semibold text-primary-600">
                                            {product.price.toLocaleString()} Kz
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 text-xs rounded-full ${product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'}`}>
                                                {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-gray-600">
                                            {product.views || 0}
                                        </td>
                                        <td className="px-6 py-4">
                                            {getStatusBadge(product.status)}
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex gap-2">
                                                <Link 
                                                    to={`/product/${product.id}`} 
                                                    className="text-blue-600 hover:text-blue-800"
                                                    title="Visualizar"
                                                >
                                                    <FiEye size={18} />
                                                </Link>
                                                <button 
                                                    onClick={() => deleteProduct(product.id)} 
                                                    className="text-red-600 hover:text-red-800"
                                                    title="Remover"
                                                >
                                                    <FiTrash2 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SellerDashboard;
